Trigger.script:
Yso = Yso or {} Yso._predict = Yso._predict or { last = 0 }
local now = (type(getEpoch)=="function" and getEpoch()) or os.time() if (now - (Yso._predict.last or 0)) < 5 then return end Yso._predict.last = now
-- NOTE: If you do not have a client-side 'curing predict' alias, the -- in-game command is typically: CURING AFFLICTIONS ADD <affliction>. send("curing predict brokenleftleg") send("curing predict brokenrightleg")

Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.energy = true
deleteLine()
cecho("\n<SteelBlue>[Magi] <ansi_light_magenta>(HEAL BURST READY!).\n")

Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.energy = false
deleteLine()
cecho("\n<SteelBlue>[Magi] <ansi_light_red>(HEAL BURST USED!).\n")
cecho("<SteelBlue>[Magi] <ansi_light_red>(EMBED ENERGISE!).\n")

Alias.script:
Yso = Yso or {} Yso.util = Yso.util or {}
if type(Yso.util.toggle_route_alias) ~= "function" then cecho("<orange>[YSO] route controller unavailable; check Mudlet load order.<reset>\n") return end
local ok, why = false, "controller_unavailable" if type(Yso.util.toggle_route_alias) == "function" then ok, why = Yso.util.toggle_route_alias("alchemist_group_damage", "alias:adam") end if ok ~= true then cecho("<orange>[YSO] adam toggle failed: " .. tostring(why or "unknown") .. "<reset>\n") end

Yso = Yso or {} Yso.util = Yso.util or {}
if type(Yso.util.toggle_route_alias) ~= "function" then cecho("<orange>[YSO] route controller unavailable; check Mudlet load order.<reset>\n") return end
local ok, why = false, "controller_unavailable" if type(Yso.util.toggle_route_alias) == "function" then ok, why = Yso.util.toggle_route_alias("alchemist_duel_route", "alias:aduel") end if ok ~= true then cecho("<orange>[YSO] aduel toggle failed: " .. tostring(why or "unknown") .. "<reset>\n") end

local targets = {}
for i = 2, 4 do local tgt = matches[i] if tgt and tgt ~= "" then targets[#targets + 1] = tgt end end
if #targets > 0 then send("queue prepend eqbal cast stormhammer at " .. table.concat(targets, " and ")) end

Script.script:
--========================================================-- -- Yso.state wiring (DEPRECATED) -- -- NOTE: -- GMCP Char.Vitals plumbing is now centralized in: -- -- This stub remains only to kill any legacy handler IDs. --========================================================--
Yso = Yso or {} Yso._eh = Yso._eh or {}
if Yso._eh.vitals then pcall(killAnonymousEventHandler, Yso._eh.vitals) Yso._eh.vitals = nil end

-- Auto-exported from Mudlet package script: Cureset Baselines -- DO NOT EDIT IN XML; edit this file instead.
Legacy = Legacy or {} Legacy.Curing = Legacy.Curing or {} Legacy.Curing.Prios = Legacy.Curing.Prios or {}
Legacy.Curing.ActiveServerSet = Legacy.Curing.ActiveServerSet or "legacy" Legacy.Curing.Prios.baseSets = Legacy.Curing.Prios.baseSets or {} Legacy.Curing.Prios.capture = Legacy.Curing.Prios.capture or { active=false, set=nil, lastPrio=nil }
function Legacy.Curing.Prios.UseBaseline(set) set = (set or Legacy.Curing.ActiveServerSet or "legacy"):lower() local base = Legacy.Curing.Prios.baseSets[set] if not base then return false end
-- This is what Reprio() uses as “default” Legacy.Curing.Prios.legacy = base return true end
function Legacy.Curing.SwitchServerSet(set) set = (set or "legacy"):lower() local changed = (Legacy.Curing.ActiveServerSet ~= set)
if changed then Legacy.Curing.ActiveServerSet = set send("curingset switch " .. set) end
-- If we don't have a baseline cached for this set, pull it once. if not Legacy.Curing.Prios.baseSets[set] then tempTimer(0.2, function() send("curing priority list") end) else -- Apply baseline only when transitioning, or if legacy baseline isn't already pointing at this base set. if changed or Legacy.Curing.Prios.legacy ~= Legacy.Curing.Prios.baseSets[set] then Legacy.Curing.Prios.UseBaseline(set) end end end

Yso = Yso or {}
Yso.magi = Yso.magi or {}
Yso.magi.defs = Yso.magi.defs or {}

local M = Yso.magi.defs

M.state = M.state or {
  class_name = "",
}

local function _vitals()
  return (gmcp and gmcp.Char and gmcp.Char.Vitals) or {}
end

local function _status()
  return (gmcp and gmcp.Char and gmcp.Char.Status) or {}
end

function M.get_hp_percent()
  local v = _vitals()
  local hp = tonumber(v.hp)
  local maxhp = tonumber(v.maxhp)

  if not hp or not maxhp or maxhp <= 0 then
    return nil
  end

  return (hp / maxhp) * 100
end

function M.get_class()
  local s = _status()
  local cls = s.class or s.classname or M.state.class_name or ""
  return tostring(cls)
end

function M.is_magi()
  return M.get_class():lower() == "magi"
end

function M.set_class(classname)
  M.state.class_name = tostring(classname or "")
end
